proc sql;
 create table cal.funda_industryn as
 select a.*, b.*
 from cal.funda_industry as a
 left join cal.company as b on a.gvkey=b.gvkey;
quit;

proc means data=cal.compc02 noprint;
 by datadate;
 var ael1 ael2 acl1 acl2 aegl1 acgl1 invest investl1 investg;
 output out=cal.compc03 mean=/autoname;
run;

proc sql;
 create table cal.compc04 as
 select a.*, b.*
 from cal.compc02 as a
 left join cal.compc03 as b on a.datadate=b.datadate;
quit;

data cal.compc04;
 set cal.compc04;
 ael1=ael1-ael1_mean;
 ael2=ael2-ael2_mean;
 acl1=acl1-acl1_mean;
 acl2=acl2-acl2_mean;
 aegl1=aegl1-aegl1_mean;
 acgl1=acgl1-acgl1_mean;
 invest=invest-invest_mean;
 investl1=investl1-investl1_mean;
 investg=investg-investg_mean;
run;

proc sql;
 create table cal.funda_industryn as
 select a.*, b.*
 from cal.funda_industry as a
 left join cal.company as b on a.gvkey=b.gvkey;
quit;

/*1-2) Keep relevant variables*/
data cal.comp;
 set cal.funda_industryn;
 keep gvkey conml cik datadate fyear at indfmt ppegt ppent revt sale oiadp oibdp oancf ni ibc dpc recch invch apalch txach aoloch uniami capxv sppe curcd curncd sic sich loc incorp exchg prcc_c act che lct dlc txp dp fic naicsh;

proc univariate data=cal.compc04 noprint;
 by year;
 var ael1 ael2 acl1 acl2 aegl1 acgl1 invest investl1 investg;
 output out=cal.compc05 pctlpts=2 98 pctlpre=ael1_ ael2_ acl1_ acl2_ aegl1_ acgl1_ invest_ investl1_ investg_ pctlname=p2 p98;

